import React, { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";

const EASE_APPLE = [0.22, 1, 0.36, 1];

const YUME_LOGO_SRC = "data:image/png;base64,";

function YumeLogo({ height = 30 }) {
  return (
    <img src={YUME_LOGO_SRC} alt="YUME" style={{ height, width: "auto", display: "block" }} />
  );
}

// 로딩 중 서버 진행상황(SSE)이 잠깐 조용할 때 보여줄 필러 문구 — 사용자가 붙여넣은
// 문장을 조각내서 "이 부분을 보는 중"처럼 보이게 해, 실제로 아무 일도 안 하는 것처럼
// (버퍼링처럼) 느껴지지 않게 한다.
function buildFillerMessages(text) {
  const pieces = text
    .split(/(?<=[.!?。！？\n])\s*/)
    .map((s) => s.trim())
    .filter((s) => s.length > 4);
  const source = pieces.length > 0 ? pieces : [text.trim()];
  const fillers = source.slice(0, 8).map((p) => {
    const short = p.length > 24 ? p.slice(0, 24) + "…" : p;
    return `"${short}" 부분을 분석하는 중…`;
  });
  return fillers.length > 0 ? fillers : ["내용을 분석하는 중…"];
}

const PLACEHOLDER = `여기에 ChatGPT, 클로드, 제미나이 등 AI의 답변을 그대로 붙여넣으세요.
법률, 의료, 금융, 역사, 과학 등 어떤 주제든 상관없습니다.

예시: "비타민 C를 하루 10g 이상 섭취하면 감기를 완전히 예방할 수 있다는 연구가 2021년 하버드 의대에서 발표됐다..."`;

const VERDICT = {
  confirmed: { label: "확인됨", bg: "#E7F6EE", color: "#1F9D66", glyph: "✓" },
  false: { label: "사실과 다름", bg: "#FBE9E7", color: "#C6402F", glyph: "✕" },
  uncertain: { label: "판단 보류", bg: "#FDF0DC", color: "#B4690E", glyph: "!" },
};
const VBORDER = { confirmed: "#E6EFE9", false: "#F5D8D3", uncertain: "#F3E3C4" };
const VBG = { confirmed: "#F9FBF9", false: "#FDF4F3", uncertain: "#FFFBF3" };

const PLANS = {
  free: { label: "무료", price: "0원", period: "", tagline: "일상적인 사실관계 확인", features: ["간단한 사실 주장 확인", "웹검색 기반 교차검증", "검증 기록 최근 50건"] },
  standard: { label: "스탠다드", price: "9,000원", period: "/월", tagline: "법률·의료 등 전문 분야 답변까지", features: ["무료 플랜 전체 포함", "법률 주장: 법제처 공식 데이터 이중검증", "검증 기록 무제한 저장", "우선 처리 속도"] },
  expert: { label: "전문가", price: "29,000원", period: "/월", tagline: "조문·판례를 직접 대조하는 수준의 정확도", features: ["스탠다드 전체 포함", "조문·판례 원문 대조 상세 리포트", "여러 건 한 번에 검증(배치)", "API 사용량 포함", "우선 지원"] },
};

